/**
 * video.js — fast YouTube embeds ("facade" pattern).
 *
 * The page only loads a small thumbnail. The real YouTube player (~1 MB of
 * scripts) is created when the visitor presses play, so videos cost nothing
 * for page speed. We use youtube-nocookie.com (no tracking cookies until play).
 *
 * To feel instant, we warm up the connection when the pointer hovers or the
 * link gets keyboard focus, before the click.
 *
 * Markup contract (generated by scripts/partials.mjs → videos()):
 *   <a class="video__facade" href="https://www.youtube.com/watch?v=ID"
 *      data-video-id="ID" data-video-title="Title"> <img …> </a>
 * Without JavaScript the link simply opens the video on YouTube.
 */
import { $$, el } from './dom.js';

const EMBED_ORIGIN = 'https://www.youtube-nocookie.com';
const ID_PATTERN = /^[\w-]{11}$/; // YouTube ids are 11 URL-safe characters

let warmedUp = false;
function warmUp() {
  if (warmedUp) return;
  warmedUp = true;
  for (const href of [EMBED_ORIGIN, 'https://www.google.com', 'https://i.ytimg.com']) {
    document.head.append(el('link', { rel: 'preconnect', href, crossorigin: '' }));
  }
}

function play(facade) {
  const id = facade.dataset.videoId;
  if (!ID_PATTERN.test(id)) return; // never build a URL from unexpected input
  const iframe = el('iframe', {
    src: `${EMBED_ORIGIN}/embed/${id}?autoplay=1&rel=0&playsinline=1&modestbranding=1`,
    title: facade.dataset.videoTitle || 'Earthens video',
    allow: 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture',
    allowfullscreen: true,
    referrerpolicy: 'strict-origin-when-cross-origin',
    class: 'video__frame',
  });
  facade.replaceWith(iframe);
  iframe.focus();
}

export function initVideos() {
  const facades = $$('[data-video-id]');
  if (!facades.length) return;
  facades.forEach((facade) => {
    facade.addEventListener('pointerenter', warmUp, { once: true });
    facade.addEventListener('focus', warmUp, { once: true });
    facade.addEventListener('click', (event) => {
      // Let modified clicks (new tab etc.) behave like a normal link.
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.button !== 0) return;
      event.preventDefault();
      warmUp();
      play(facade);
    });
  });
}
